'use client'

/**
 * The unparty button (#1095): lists every remaining reference to unparty — the
 * brand, not the frame — so a buyer can replace each one. Done at zero.
 *
 * Reads src/data/unpartyRefsManifest.json through /api/admin/unparty-refs
 * (regenerated by scripts/generate-unparty-refs.js on every build and before
 * `npm run dev`), grouped by category in replacement order: identity first,
 * then the domain, then any example projects (the public copy leaves them
 * out; delete what remains, never rename: renaming changes URLs), author
 * data last. File paths count too, and so does the SETUP. curriculum, which
 * is why this is the last step (D4, D6, D8 in #1244).
 * unppp is frame vocabulary (like "story" or "cover") and never counts.
 * Reaching zero completes the SETUP. "brand" step automatically.
 */

import { useEffect, useState } from 'react'
import { useTheme } from '../../contexts/ThemeContext'
import type { UnpartyRefsManifest, UnpartyRefFile } from '@/lib/unparty-refs'

type UnpartyRefsResponse = UnpartyRefsManifest & {
  setupStep: { id: string; seeded: boolean; completed: boolean }
}

function fileUrl(manifest: UnpartyRefsManifest, file: string, line?: number) {
  if (!manifest.repo) return null
  const anchor = line && line > 0 ? `#L${line}` : ''
  return `${manifest.repo}/blob/${manifest.branch}/${encodeURI(file)}${anchor}`
}

function FileRow({ manifest, entry, color }: { manifest: UnpartyRefsManifest; entry: UnpartyRefFile; color: string }) {
  const href = fileUrl(manifest, entry.file, entry.lines[0]?.[0])
  return (
    <details className="group border-b last:border-b-0" style={{ borderColor: `${color}15` }}>
      <summary className="flex cursor-pointer items-baseline justify-between gap-3 px-2 py-1.5 font-google-sans-code text-xs transition-colors hover:bg-[var(--background-highlight)]">
        <span className="min-w-0 truncate" style={{ color: 'var(--foreground)' }}>{entry.file}</span>
        <span className="flex shrink-0 items-baseline gap-2">
          <span style={{ color: 'var(--text-muted)' }}>×{entry.count}</span>
          {href && (
            <a
              href={href}
              target="_blank"
              rel="noopener noreferrer"
              className="underline"
              style={{ color }}
              onClick={(event) => event.stopPropagation()}
            >
              open ↗
            </a>
          )}
        </span>
      </summary>
      <ul className="px-2 pb-2">
        {entry.lines.map(([line, match, occurrences], index) => {
          const lineHref = fileUrl(manifest, entry.file, line)
          return (
            <li key={`${line}-${match}-${index}`} className="flex items-baseline gap-2 py-0.5 font-google-sans-code text-[11px]">
              {lineHref && line > 0 ? (
                <a href={lineHref} target="_blank" rel="noopener noreferrer" className="shrink-0 underline" style={{ color }}>
                  L{line}
                </a>
              ) : (
                <span className="shrink-0" style={{ color: 'var(--text-muted)' }}>{line > 0 ? `L${line}` : 'file'}</span>
              )}
              <span className="min-w-0 truncate" style={{ color: 'var(--text-muted)' }}>
                {match}
                {occurrences ? ` ×${occurrences}` : ''}
              </span>
            </li>
          )
        })}
      </ul>
    </details>
  )
}

export default function UnpartyButtonPage() {
  const { colorValue } = useTheme()
  const [manifest, setManifest] = useState<UnpartyRefsResponse | null>(null)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    // The SETUP. steps that check themselves get checked first (one checker,
    // src/lib/setup-verify.ts), so the brand step's state below is current
    fetch('/api/admin/setup/verify', { method: 'POST' })
      .catch(() => null)
      .then(() => fetch('/api/admin/unparty-refs'))
      .then((res) => {
        if (!res.ok) throw new Error(`Request failed (${res.status})`)
        return res.json()
      })
      .then(setManifest)
      .catch((err) => setError(err instanceof Error ? err.message : 'Failed to load'))
  }, [])

  if (error) {
    return (
      <div className="rounded-xl border p-6 font-google-sans-code text-sm" style={{ borderColor: `${colorValue}20`, color: 'var(--text-muted)' }}>
        Could not load the unparty references manifest: {error}
      </div>
    )
  }

  if (!manifest) {
    return (
      <div className="rounded-xl border p-6 font-vt323 text-lg" style={{ borderColor: `${colorValue}20`, color: 'var(--text-muted)' }}>
        counting...
      </div>
    )
  }

  if (!manifest.measured) {
    return (
      <div className="rounded-xl border p-6 text-left" style={{ backgroundColor: 'var(--background)', borderColor: `${colorValue}20` }}>
        <h2 className="mb-2 font-google-sans-code text-sm font-bold uppercase" style={{ color: colorValue }}>
          UNPARTY.
        </h2>
        <div className="font-vt323 text-3xl leading-none" style={{ color: 'var(--foreground)' }}>
          not counted here.
        </div>
        <p className="mt-2 font-google-sans-code text-xs" style={{ color: 'var(--text-muted)' }}>
          {manifest.reason}
        </p>
      </div>
    )
  }

  const remaining = manifest.total.matches + manifest.total.paths

  return (
    <div className="space-y-6">
      {/* The button: how much unparty is left. Done at zero. */}
      <div className="rounded-xl border p-6 text-left" style={{ backgroundColor: 'var(--background)', borderColor: `${colorValue}20` }}>
        <h2 className="mb-2 font-google-sans-code text-sm font-bold uppercase" style={{ color: colorValue }}>
          UNPARTY.
        </h2>
        <div className="font-vt323 text-7xl leading-none" style={{ color: manifest.done ? colorValue : 'var(--foreground)' }}>
          {remaining.toLocaleString()}
        </div>
        <p className="mt-2 font-google-sans-code text-xs" style={{ color: 'var(--text-muted)' }}>
          {manifest.done
            ? 'no unparty references remain - this copy is yours. ✅'
            : `unparty references remaining (${manifest.total.matches.toLocaleString()} matches in ${manifest.total.files.toLocaleString()} files, ${manifest.total.paths.toLocaleString()} file paths). Replace each one below - the step is done at zero.`}
        </p>
        <p className="mt-2 font-google-sans-code text-[11px]" style={{ color: 'var(--text-muted)' }}>
          counted at build time ({new Date(manifest.generatedAt).toLocaleString()}) - regenerates on every build and npm run dev
          {manifest.setupStep.seeded && (
            <> · SETUP. step {manifest.setupStep.completed ? 'complete ✅' : 'pending'}</>
          )}
        </p>
      </div>

      {/* What never counts: the frame a buyer keeps */}
      <div className="rounded-xl border p-6" style={{ backgroundColor: 'var(--background)', borderColor: `${colorValue}20` }}>
        <h3 className="mb-2 font-google-sans-code text-sm font-bold uppercase" style={{ color: colorValue }}>
          KEPT. (the frame, not the brand)
        </h3>
        <p className="font-google-sans-code text-xs" style={{ color: 'var(--text-muted)' }}>
          &ldquo;{manifest.vocabulary.pattern}&rdquo; - {manifest.vocabulary.note} Currently {manifest.vocabulary.matches.toLocaleString()} uses
          in {manifest.vocabulary.files.toLocaleString()} files.
        </p>
        <details className="mt-3">
          <summary className="cursor-pointer font-google-sans-code text-xs underline" style={{ color: colorValue }}>
            allowlisted frame files ({manifest.allowlist.length})
          </summary>
          <ul className="mt-2 space-y-0.5">
            {manifest.allowlist.map((file) => (
              <li key={file} className="font-google-sans-code text-[11px]" style={{ color: 'var(--text-muted)' }}>
                {file}
              </li>
            ))}
          </ul>
        </details>
      </div>

      {/* Every reference, grouped by what it is, in replacement order */}
      {manifest.categories.map((category) => (
        <div key={category.id} className="rounded-xl border p-6" style={{ backgroundColor: 'var(--background)', borderColor: `${colorValue}20` }}>
          <h3 className="mb-1 font-google-sans-code text-sm font-bold uppercase" style={{ color: colorValue }}>
            {category.order}. {category.label}.
            <span className="ml-2 font-normal normal-case" style={{ color: 'var(--text-muted)' }}>
              {category.matches.toLocaleString()} {category.matches === 1 ? 'match' : 'matches'} in {category.files.toLocaleString()} {category.files === 1 ? 'file' : 'files'}
            </span>
          </h3>
          <p className="mb-4 font-google-sans-code text-xs" style={{ color: 'var(--text-muted)' }}>
            {category.description}
          </p>
          {category.entries.length === 0 ? (
            <p className="font-google-sans-code text-xs" style={{ color: colorValue }}>done. ✅</p>
          ) : (
            <div className="rounded-lg border" style={{ borderColor: `${colorValue}15` }}>
              {category.entries.map((entry) => (
                <FileRow key={entry.file} manifest={manifest} entry={entry} color={colorValue} />
              ))}
            </div>
          )}
        </div>
      ))}

      {/* File and route paths: delete, never rename - renaming changes URLs */}
      <div className="rounded-xl border p-6" style={{ backgroundColor: 'var(--background)', borderColor: `${colorValue}20` }}>
        <h3 className="mb-1 font-google-sans-code text-sm font-bold uppercase" style={{ color: colorValue }}>
          5. paths.
          <span className="ml-2 font-normal normal-case" style={{ color: 'var(--text-muted)' }}>
            {manifest.total.paths.toLocaleString()} {manifest.total.paths === 1 ? 'file' : 'files'}
          </span>
        </h3>
        <p className="mb-4 font-google-sans-code text-xs" style={{ color: 'var(--text-muted)' }}>
          Tracked files whose path contains &ldquo;unparty&rdquo;: route folders, covers, article files, brand images. They
          count toward zero. Delete or replace each one - never rename a page in place, renaming changes public URLs.
        </p>
        {manifest.paths.length === 0 ? (
          <p className="font-google-sans-code text-xs" style={{ color: colorValue }}>done. ✅</p>
        ) : (
          <ul className="max-h-96 space-y-0.5 overflow-y-auto rounded-lg border p-2" style={{ borderColor: `${colorValue}15` }}>
            {manifest.paths.map((file) => {
              const href = fileUrl(manifest, file)
              return (
                <li key={file} className="truncate font-google-sans-code text-[11px]">
                  {href ? (
                    <a href={href} target="_blank" rel="noopener noreferrer" className="underline" style={{ color: 'var(--text-muted)' }}>
                      {file}
                    </a>
                  ) : (
                    <span style={{ color: 'var(--text-muted)' }}>{file}</span>
                  )}
                </li>
              )
            })}
          </ul>
        )}
      </div>
    </div>
  )
}
